diff --git a/src/test/java/tools/jackson/databind/struct/UnwrappedPropertyConflict2883Test.java b/src/test/java/tools/jackson/databind/struct/UnwrappedPropertyConflict2883Test.java
index ee6620666..b0fe400db 100644
--- a/src/test/java/tools/jackson/databind/struct/UnwrappedPropertyConflict2883Test.java
+++ b/src/test/java/tools/jackson/databind/struct/UnwrappedPropertyConflict2883Test.java
@@ -135,10 +135,12 @@ public class UnwrappedPropertyConflict2883Test extends DatabindTestUtil
         InvalidDefinitionException ex = assertThrows(
                 InvalidDefinitionException.class,
                 () -> MAPPER.writeValueAsString(new OuterConflict()));
-        verifyException(ex, "Conflict between unwrapped property");
+        verifyException(ex, "Conflict for type");
         verifyException(ex, "'b'");
         // Error should also identify the offending unwrapped type
         verifyException(ex, "InnerC");
+        // [databind#6028]: ...as well as the type that declares the unwrapped mapping
+        verifyException(ex, "OuterConflict");
     }

     @Test
@@ -153,7 +155,7 @@ public class UnwrappedPropertyConflict2883Test extends DatabindTestUtil
         InvalidDefinitionException ex = assertThrows(
                 InvalidDefinitionException.class,
                 () -> MAPPER.writeValueAsString(new TwoUnwrappedConflict()));
-        verifyException(ex, "Conflict between unwrapped property");
+        verifyException(ex, "unwrapped property");
         verifyException(ex, "'id'");
     }

@@ -172,7 +174,7 @@ public class UnwrappedPropertyConflict2883Test extends DatabindTestUtil
         InvalidDefinitionException ex = assertThrows(
                 InvalidDefinitionException.class,
                 () -> MAPPER.writeValueAsString(new OuterRenameConflict()));
-        verifyException(ex, "Conflict between unwrapped property");
+        verifyException(ex, "unwrapped property");
         verifyException(ex, "'id'");
     }

@@ -186,7 +188,7 @@ public class UnwrappedPropertyConflict2883Test extends DatabindTestUtil
         InvalidDefinitionException ex = assertThrows(
                 InvalidDefinitionException.class,
                 () -> mapper.writeValueAsString(new OuterNamingStrategyConflict()));
-        verifyException(ex, "Conflict between unwrapped property");
+        verifyException(ex, "unwrapped property");
         verifyException(ex, "'foo_bar'");
     }

diff --git a/src/test/java/tools/jackson/databind/struct/UnwrappedWithConverter6017Test.java b/src/test/java/tools/jackson/databind/struct/UnwrappedWithConverter6017Test.java
index f6ab101ec..a0cd0a6d5 100644
--- a/src/test/java/tools/jackson/databind/struct/UnwrappedWithConverter6017Test.java
+++ b/src/test/java/tools/jackson/databind/struct/UnwrappedWithConverter6017Test.java
@@ -77,7 +77,7 @@ public class UnwrappedWithConverter6017Test extends DatabindTestUtil
     public void testUnwrappedConverterPropertyConflictDetected() {
         DatabindException e = assertThrows(DatabindException.class,
                 () -> MAPPER.writeValueAsString(new OuterConflict()));
-        assertTrue(e.getMessage().contains("Conflict between unwrapped property 'x'"),
+        assertTrue(e.getMessage().contains("unwrapped property 'x'"),
                 "Unexpected message: " + e.getMessage());
     }
 }
